# Ki-kare (POV) saldirisi: LSB ekleme cift degerleri esitler mi?
from math import exp, factorial

def chi2_p(x, df):
    # df cift oldugunda kesin: P(X > x) = exp(-x/2) * toplam_{j<df/2} (x/2)^j / j!
    return exp(-x / 2) * sum((x / 2) ** j / factorial(j) for j in range(df // 2))

kapak = [(1200, 800), (950, 1050), (600, 400), (300, 500), (700, 700)]  # (h[2k], h[2k+1])

def chi2(ciftler):
    toplam = 0.0
    for h0, h1 in ciftler:
        beklenen = (h0 + h1) / 2
        toplam += (h0 - beklenen) ** 2 / beklenen
    return toplam

def gom(ciftler, alpha):
    # LSB ekleme: h0' = h0(1-a/2) + h1(a/2)
    return [(h0 * (1 - alpha / 2) + h1 * (alpha / 2),
             h1 * (1 - alpha / 2) + h0 * (alpha / 2)) for h0, h1 in ciftler]

df = len(kapak) - 1
print("serbestlik derecesi = %d" % df)
print("%8s %12s %12s %s" % ("alpha", "chi2", "p", "karar"))
for alpha in [0.0, 0.25, 0.5, 0.75, 1.0]:
    c = chi2(gom(kapak, alpha))
    p = chi2_p(c, df)
    print("%8.2f %12.4f %12.6f %s" % (alpha, c, p, "gomme var" if p > 0.5 else "temiz"))

# Donem sentezi: gereksinimden yonteme karar agaci
def oner(gereksinim):
    g = gereksinim
    if g["tam_geri_alma"]:
        return "tersinir damgalama (histogram kaydirma / fark genisletme)"
    if g["amac"] == "butunluk":
        return "kirilgan/yari kirilgan damga + kriptografik imza (ayri ustveri)"
    if g["amac"] == "sahiplik":
        if g["alici_takibi"]:
            return "gizli anlasmaya dayanikli parmak izleme (Tardos tipi kod)"
        return "dayanikli damga: DCT/DWT orta frekans + yayili spektrum, kor tespit"
    if g["amac"] == "gizli_haberlesme":
        if g["kanal_kayipli"]:
            return "DCT alaninda dusuk oranli gomme + hata duzeltme"
        return "dusuk oranli matris gomme (Hamming) + once sifreleme"
    return "tanimsiz"

